def fib(n):
    a, b = 1, 1
    for _ in range(3, n+1):
        a, b = b, a+b
    return b if n>1 else a
print(fib(30))

def count_primes(limit):
    sieve = [True] * limit
    sieve[0:2] = [False, False]
    for i in range(2, int(limit**0.5) + 1):
        if sieve[i]:
            sieve[i*i:limit:i] = [False] * len(range(i*i, limit, i))
    return sum(sieve)

print(count_primes(10000))

